                                this.V[nibble2] = this.V[nibble3];
                                break;
                            case 0x1: // 8XY1 - VX = VX OR VY
                                this.V[nibble2] |= this.V[nibble3];
                                break;
                            case 0x2: // 8XY2 - VX = VX AND VY
                                this.V[nibble2] &= this.V[nibble3];
                                break;
                            case 0x3: // 8XY3 - VX = VX XOR VY
                                this.V[nibble2] ^= this.V[nibble3];
                                break;
                            case 0x4: // 8XY4 - VX = VX + VY, VF = carry
                                const sum = this.V[nibble2] + this.V[nibble3];
                                this.V[nibble2] = sum & 0xFF;
                                this.V[0xF] = (sum > 0xFF) ? 1 : 0;
                                break;
                            case 0x5: // 8XY5 - VX = VX - VY, VF = borrow
                                const diff = this.V[nibble2] - this.V[nibble3];
                                this.V[nibble2] = diff & 0xFF;
                                this.V[0xF] = (this.V[nibble2] > this.V[nibble3]) ? 1 : 0;
                                break;
                            case 0x6: // 8XY6 - VX = VX >> 1, VF = LSB
                                this.V[0xF] = this.V[nibble2] & 0x01;
                                this.V[nibble2] = (this.V[nibble2] >> 1) & 0xFF;
                                break;
                            case 0x7: // 8XY7 - VX = VY - VX, VF = NOT borrow
                                const diff2 = this.V[nibble3] - this.V[nibble2];
                                this.V[nibble2] = diff2 & 0xFF;
                                this.V[0xF] = (this.V[nibble2] < this.V[nibble3]) ? 1 : 0;
                                break;
                            case 0xE: // 8XYE - VX = VX << 1, VF = MSB
                                this.V[0xF] = (this.V[nibble2] & 0x80) >> 7;
                                this.V[nibble2] = (this.V[nibble2] << 1) & 0xFF;
                                break;
                        }
                        break;

                    case 0x9: // 9XY0 - Skip next if VX != VY
                        if (this.V[nibble2] !== this.V[nibble3]) {
                            this.PC += 2;
                        }
                        break;

                    case 0xA: // ANNN - I = nnnn
                        this.I = nNNN;
                        break;

                    case 0xB: // Bnnn - Jump to V0 + nnnn
                        this.PC = (this.V[0] + nNNN) & 0xFFFF;
                        break;

                    case 0xC: // CXNN - VX = random byte AND NN
                        const random = Math.floor(Math.random() * 0x100);
                        this.V[nibble2] = random & nn;
                        break;

                    case 0xD: // DXYN - Draw sprite at (VX, VY), N bytes from I, collision in VF
                        const x = this.V[nibble2];
                        const y = this.V[nibble3];
                        const height = nibble4;
                        const width = 8;

                        this.V[0xF] = 0;

                        for (let row = 0; row < height; row++) {
                            const spriteByte = this.memory[this.I + row];
                            for (let col = 0; col < width; col++) {
                                const pixel = (spriteByte >> (7 - col)) & 0x01;
                                const xPos = (x + col) % 64;
                                const yPos = (y + row) % 32;
                                const index = yPos * 64 + xPos;

                                if (pixel === 1) {
                                    if (this.display[index] === 1) {
                                        this.V[0xF] = 1; // Collision
                                    }
                                    this.display[index] ^= 1; // XOR operation
                                }
                            }
                        }

                        // Update overlay for sprite preview
                        this.updateOverlay(x, y, height);
                        break;

                    case 0xE:
                        // EX9E - Skip next if key VX is pressed
                        if (opcode === (0xE000 | nibble2 << 8 | 0x9E)) {
                            if (this.keys[this.V[nibble2]] > 0) {
                                this.PC += 2;
                            }
                        }
                        // EXA1 - Skip next if key VX is NOT pressed
                        else if (opcode === (0xE000 | nibble2 << 8 | 0xA1)) {
                            if (this.keys[this.V[nibble2]] === 0) {
                                this.PC += 2;
                            }
                        }
                        break;

                    case 0xF:
                        switch (nibble4) {
                            case 0x0: // FX07 - VX = delay timer
                                this.V[nibble2] = this.delayTimer;
                                break;
                            case 0x1: // FX15 - delay timer = VX
                                this.delayTimer = this.V[nibble2];
                                break;
                            case 0x2: // FX18 - sound timer = VX
                                this.soundTimer = this.V[nibble2];
                                break;
                            case 0x3: // FX1E - I = I + VX
                                this.I = (this.I + this.V[nibble2]) & 0xFFFF;
                                break;
                            case 0x4: // FX29 - I = address of font sprite VX
                                this.I = 0x050 + (this.V[nibble2] * 5);
                                break;
                            case 0x5: // FX33 - BCD conversion of VX
                                const value = this.V[nibble2];
                                this.memory[this.I] = Math.floor(value / 100);
                                this.memory[this.I + 1] = Math.floor((value % 100) / 10);
                                this.memory[this.I + 2] = value % 10;
                                break;
                            case 0x6: // FX06 - VX = VX >> 4 (not standard, but used)
                                this.V[nibble2] = (this.V[nibble2] >> 4) & 0x0F;
                                break;
                            case 0x7: // FX07 - VX = delay timer (duplicate of 0xF0)
                                this.V[nibble2] = this.delayTimer;
                                break;
                            case 0xA: // FX0A - Wait for key press, block until key pressed
                                for (let i = 0; i < 16; i++) {
                                    if (this.keys[i] > 0) {
                                        this.V[nibble2] = i;
                                        return; // Exit without incrementing PC
                                    }
                                }
                                // If no key pressed, stay in this instruction
                                return;
                            case 0xE: // FXE - I = I + 2 (not standard, but used)
                                this.I = (this.I + 2) & 0xFFFF;
                                break;
                            case 0xF: // FX1F - I = I + VX (duplicate of 0xF1)
                                this.I = (this.I + this.V[nibble2]) & 0xFFFF;
                                break;
                        }
                        break;
                }

                this.PC += 2;
            }

