            drawDisplay() {
                this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

                const scale = 10; // Scale factor for 64x32 to 640x320

                for (let y = 0; y < 32; y++) {
                    for (let x = 0; x < 64; x++) {
                        if (this.display[y * 64 + x] === 1) {
                            this.ctx.fillStyle = '#0f0';
                            this.ctx.fillRect(x * scale, y * scale, scale, scale);
                        }
                    }
                }
            }

            updateOverlay(x, y, height) {
                this.overlayCtx.clearRect(0, 0, this.overlayCanvas.width, this.overlayCanvas.height);

                const scale = 10;
                const width = 8;

                this.overlayCtx.fillStyle = 'rgba(0, 255, 0, 0.3)';

                for (let row = 0; row < height; row++) {
                    const spriteByte = this.memory[this.I + row];
                    for (let col = 0; col < width; col++) {
                        const pixel = (spriteByte >> (7 - col)) & 0x01;
                        if (pixel === 1) {
                            const xPos = ((x + col) % 64) * scale;
                            const yPos = ((y + row) % 32) * scale;
                            this.overlayCtx.fillRect(xPos, yPos, scale, scale);
                        }
                    }
                }
            }

            updateUI() {
                // Update registers display
                const registersDisplay = document.getElementById('registersDisplay');
                registersDisplay.innerHTML = '';

                for (let i = 0; i < 16; i++) {
                    const registerEl = document.createElement('div');
                    registerEl.className = `register ${i === 0xF ? 'VF' : ''}`;
                    registerEl.textContent = `V${i.toString(16).toUpperCase()}: ${this.V[i].toString(16).padStart(2, '0')}`;
                    registersDisplay.appendChild(registerEl);
                }

                // Update other debugger info
                document.getElementById('indexRegister').textContent = `0x${this.I.toString(16).padStart(4, '0')}`;
                document.getElementById('programCounter').textContent = `0x${this.PC.toString(16).padStart(4, '0')}`;

                // Update stack display
                const stackDisplay = document.getElementById('stackDisplay');
                if (this.stackSize === 0) {
                    stackDisplay.textContent = '[empty]';
                } else {
                    let stackText = '';
                    for (let i = 0; i < this.stackSize; i++) {
                        stackText += `0x${this.stack[i].toString(16).padStart(4, '0')}\n`;
                    }
                    stackDisplay.textContent = stackText;
                }

                // Update decoded instruction
                if (this.PC < 0xFFF - 1) {
                    const opcode = (this.memory[this.PC] << 8) | this.memory[this.PC + 1];
                    document.getElementById('decoded').textContent = this.getDecodedInstruction(opcode);
                }

                // Draw display
                this.drawDisplay();
            }

            getDecodedInstruction(opcode) {
                const nibble1 = (opcode & 0xF000) >> 12;
                const nibble2 = (opcode & 0x0F00) >> 8;
                const nibble3 = (opcode & 0x00F0) >> 4;
                const nibble4 = opcode & 0x000F;
                const nn = opcode & 0x00FF;
                const n = opcode & 0x000F;

                let decoded = `0x${opcode.toString(16).padStart(4, '0').toUpperCase()}`;

                switch (nibble1) {
                    case 0x0:
                        if (opcode === 0x00E0) {
                            decoded += ' - CLS';
                        } else if (opcode === 0x00EE) {
                            decoded += ' - RET';
                        } else {
                            decoded += ' - SYS';
                        }
                        break;
                    case 0x1:
                        decoded += ` - JP 0x${nNNN.toString(16).padStart(4, '0')}`;
                        break;
                    case 0x2:
                        decoded += ` - CALL 0x${nNNN.toString(16).padStart(4, '0')}`;
                        break;
                    case 0x3:
                        decoded += ` - SE V${nibble2} 0x${nn.toString(16).padStart(2, '0')}`;
                        break;
                    case 0x4:
                        decoded += ` - SNE V${nibble2} 0x${nn.toString(16).padStart(2, '0')}`;
                        break;
                    case 0x5:
                        decoded += ` - SE V${nibble2} V${nibble3}`;
                        break;
                    case 0x6:
                        decoded += ` - LD V${nibble2} 0x${nn.toString(16).padStart(2, '0')}`;
                        break;
                    case 0x7:
                        decoded += ` - ADD V${nibble2} 0x${nn.toString(16).padStart(2, '0')}`;
                        break;
                    case 0x8:
                        switch (nibble4) {
                            case 0x0: decoded += ' - LD V${nibble2} V${nibble3}'; break;
                            case 0x1: decoded += ' - OR V${nibble2} V${nibble3}'; break;
                            case 0x2: decoded += ' - AND V${nibble2} V${nibble3}'; break;
                            case 0x3: decoded += ' - XOR V${nibble2} V${nibble3}'; break;
                            case 0x4: decoded += ' - ADD V${nibble2} V${nibble3}'; break;
                            case 0x5: decoded += ' - SUB V${nibble2} V${nibble3}'; break;
                            case 0x6: decoded += ' - SHR V${nibble2}'; break;
                            case 0x7: decoded += ' - SUBN V${nibble2} V${nibble3}'; break;
                            case 0xE: decoded += ' - SHL V${nibble2}'; break;
                        }
                        break;
                    case 0x9:
                        decoded += ` - SNE V${nibble2} V${nibble3}`;
                        break;
                    case 0xA:
                        decoded += ` - LD I 0x${nNNN.toString(16).padStart(4, '0')}`;
                        break;
                    case 0xB:
                        decoded += ` - JP V0 0x${nNNN.toString(16).padStart(4, '0')}`;
                        break;
                    case 0xC:
                        decoded += ` - RND V${nibble2} 0x${nn.toString(16).padStart(2, '0')}`;
                        break;
                    case 0xD:
                        decoded += ` - DRW V${nibble2} V${nibble3} 0x${nibble4}`;
                        break;
                    case 0xE:
                        if (opcode === (0xE000 | nibble2 << 8 | 0x9E)) {
                            decoded += ` - SKP V${nibble2}`;
                        } else if (opcode === (0xE000 | nibble2 << 8 | 0xA1)) {
                            decoded += ` - SKNP V${nibble2}`;
                        }
                        break;
                    case 0xF:
                        switch (nibble4) {
                            case 0x0: decoded += ' - LD V${nibble2} DT'; break;
                            case 0x1: decoded += ' - LD DT V${nibble2}'; break;
                            case 0x2: decoded += ' - LD ST V${nibble2}'; break;
                            case 0x3: decoded += ' - LD I I+V${nibble2}'; break;
                            case 0x4: decoded += ' - LD F V${nibble2}'; break;
                            case 0x5: decoded += ' - LD B V${nibble2}'; break;
                            case 0x6: decoded += ' - LD V${nibble2} DT'; break;
                            case 0x7: decoded += ' - LD V${nibble2} DT'; break;
                            case 0xA: decoded += ' - LD V${nibble2} K'; break;
                            case 0xE: decoded += ' - LD I I+2'; break;
                            case 0xF: decoded += ' - LD I I+V${nibble2}'; break;
                        }
                        break;
                }

                return decoded;
            }

            updateStatus(message, isError = false) {
                const statusEl = document.getElementById('status');
                statusEl.textContent = message;
                statusEl.className = `status ${isError ? 'error' : 'success'}`;

                if (isError) {
                    setTimeout(() => {
                        statusEl.className = 'status';
                        statusEl.textContent = 'Ready';
                    }, 3000);
                }
            }
